Method.Source:
public void DrawPage(TFMPage _page, TFMHtmlViewerCtrl _htmlViewer)
{
    Map								menuItemsMap;
    TFMListId						listId = _page.getListId();
    TFMPageDatasources				ds;
    Map                             translations = TFMTranslationProvider::getAllTranslationsForCurrentUserLanguage();
    str                             title;
    TFMPages                        pages = TFMPagesProvider::getAllPages();

    menuItemsMap = this.getMenuItemButtons(_page.parmId(), pages);

    if (listId)
    {
        select firstonly ds where ds.PageID == _page.parmId();
        title = TFMListVisualization::getMenuTitle(_page.parmTitle());
        TFMListVisualization::DrawList(_htmlViewer,listId,TFMListsVersion::newestVersion(listId, false),false,true,ds,0.4,title,_page.parmIcon(),menuItemsMap,null);
    }
}
